File.CreatingTakesTheOpenReservation.source:
({ before, after, command }) => {
			if (command._tag !== "CreateFile") {
				return true
			}
			return [
				after.status === before.status,
				[before.open_reservation !== 0, before.open_reservation === command.reservation].every(
					(ok) => ok,
				),
			].some((ok) => ok)
		}

SessionOutputs.ASavedTurnReplacesTheFile.source:
({ after, command, events }) => {
			if (command._tag !== "RecordSessionOutputs") {
				return true
			}
			return [
				events.length === 0,
				[after.files === command.files, after.skipped === command.skipped].every((ok) => ok),
			].some((ok) => ok)
		}
